    38→    public function guardar(Request $request): Model {
    39→        $campos_excluidos = ['_token', '_method', 'id'];
    40→
    41→        if ($request->filled('campos_excluidos')) {
    42→            $campos_excluidos = array_unique([...$campos_excluidos, ...$request->campos_excluidos]);
    43→        }
    44→
    45→        if ($request->filled('id')) {
    46→            $registro = $this->repositorio->actualizar($request->id, $request->except($campos_excluidos));
    47→        } else {
    48→            $registro = $this->repositorio->crear($request->except($campos_excluidos));
    49→        }
    50→
    51→        return $registro;
    52→    }
    53→
    54→    /**
    55→     * Obtener los datos referenciados en el historial de cambios.
    56→     *
    57→     * @param Collection $historial Historial de cambios.
    58→     * @param string $campo_id ID del campo referenciado.
    59→     * @param string $campo_filtro Campo para filtrar los datos.
    60→     * @param BaseRepository $repositorio Repositorio de los datos referenciados.
    61→     * @return Collection
    62→     * @author Daniel Beltrán
    63→     */
    64→    public function obtenerDatosReferenciados(Collection $historial, string $campo_id, string $campo_filtro, BaseRepository $repositorio): Collection {
    65→        $antiguos_ids = $historial->pluck('old_values')->pluck($campo_id)->filter()->unique()->toArray();
    66→        $nuevos_ids   = $historial->pluck('new_values')->pluck($campo_id)->filter()->unique()->toArray();
    67→        $ids          = array_unique([...$antiguos_ids, ...$nuevos_ids]);
    68→        return $repositorio->getTodo(new Request([$campo_filtro => $ids]));
    69→    }
    70→}
