   592→        $nombre_vacante = $vacante->nombre_vacante ?? 'la vacante';
   593→
   594→        if ($etapa->nombre === EtapaVacante::CONTRATADOS_NOMBRE) {
   595→            $variables = [
   596→                $nombre_candidato,
   597→                $nombre_empresa,
   598→                $nombre_vacante
   599→            ];
   600→        } elseif ($etapa->nombre === EtapaVacante::DESCARTADOS_NOMBRE) {
   601→            $variables = [];
   602→        } else {
   603→
   604→            $variables = [
